import { molde, type Molde, type Opcao, type Capitulo, type Tipo, type Cond2 } from '../../../../../engine/v2/tipos';

/**
 * Lote 3 da Fase 3: defeitos e talentos como cenas de personagem (a marca do build). Cada traço tem uma cena em que ele
 * pesa de verdade, com pessoas olhando; a opção "enfrentar" de um defeito pode superá-lo (fx.superar), e a de um talento
 * abre uma oportunidade que só ele explica.
 */
const AMIGO = { amigo: { pessoa: { papel: 'amigo', vivo: true }, opcional: true } } as const;
const RIVAL = { rival: { pessoa: { papel: 'rival', vivo: true }, opcional: true } } as const;
const MESTRE = { mestre: { pessoa: { papel: 'mestre', vivo: true }, opcional: true } } as const;

function traco(id: string, titulo: string, onde: Cond2['jogador'], tipo: Tipo, caps: Capitulo[], papeis: Molde['papeis'], cena: Molde['cena'], opcoes: Opcao[], mais = 34): Molde {
  return molde({
    id, titulo, tipo, capitulos: caps, unico: true, papeis,
    quando: { jogador: { ...onde, reinoMin: 1 } },
    relevancia: [{ se: { jogador: onde }, mais }],
    cena, opcoes,
  });
}

